<main class="py-5"><div class="container"><div class="d-flex justify-content-between align-items-center mb-4"><div><span class="badge bg-primary-subtle text-primary">Administration</span><h1 class="h2 text-primary mt-2">Tableau de bord</h1></div><div class="d-flex gap-2 flex-wrap"><a class="btn btn-outline-primary" href="/admin/menus">Menus</a><a class="btn btn-outline-primary" href="/admin/dishes">Plats</a><a class="btn btn-outline-primary" href="/admin/orders">Commandes</a><a class="btn btn-outline-primary" href="/admin/hours">Horaires</a><a class="btn btn-outline-primary" href="/admin/employees">Employés</a><a class="btn btn-outline-primary" href="/admin/comments/pending">Avis</a></div></div><div class="row g-4"><div class="col-md-6 col-xl-3"><article class="card border-0 shadow-sm"><div class="card-body"><p class="text-muted mb-1">Utilisateurs</p><p class="display-6 mb-0"><?= (int) ($stats['total_users'] ?? 0) ?></p></div></article></div><div class="col-md-6 col-xl-3"><article class="card border-0 shadow-sm"><div class="card-body"><p class="text-muted mb-1">Commandes</p><p class="display-6 mb-0"><?= (int) ($stats['total_orders'] ?? 0) ?></p></div></article></div><div class="col-md-6 col-xl-3"><article class="card border-0 shadow-sm"><div class="card-body"><p class="text-muted mb-1">En attente</p><p class="display-6 mb-0"><?= (int) ($stats['pending_orders'] ?? 0) ?></p></div></article></div><div class="col-md-6 col-xl-3"><article class="card border-0 shadow-sm"><div class="card-body"><p class="text-muted mb-1">Chiffre d'affaires</p><p class="display-6 mb-0"><?= number_format((float) ($stats['total_revenue'] ?? 0), 2, ',', ' ') ?> €</p></div></article></div></div><section class="card border-0 shadow-sm mt-4"><div class="card-body"><h2 class="h4 text-primary">Commandes par menu</h2><?php $menuStats=$stats['menu_stats']??[]; $maxOrders=0; foreach($menuStats as $s){$maxOrders=max($maxOrders,(int)($s['order_count']??0));} ?><?php if($menuStats===[]): ?><p class="text-muted">Aucune statistique disponible.</p><?php else: ?><?php foreach($menuStats as $s): ?><div class="mb-3"><div class="d-flex justify-content-between small"><span><?= $escape($s['menu_title'] ?? ('Menu #'.$s['menu_id'])) ?></span><strong><?= (int)$s['order_count'] ?> commande(s)</strong></div><div class="progress" role="img" aria-label="Comparaison du nombre de commandes"><div class="progress-bar" style="width: <?= $maxOrders>0 ? round(((int)$s['order_count']/$maxOrders)*100) : 0 ?>%"></div></div></div><?php endforeach; ?><?php endif; ?></div></section></div></main>
